/* Left Section */
.dashboard-left {
    flex: 0.6;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    top: 2rem;
    width: 100%;
}
.dashboard-left h1 {
    font-size: 2rem;
    font-weight: 700;
    color: #2A5F3B;
    text-align: center;
    flex-shrink: 0;
}
.dashboard-profile-image {
    width: 200px;
    height: auto;
    max-height: 243px;
    object-fit: cover;
    display: block;
    margin: 0 auto;
}
  
/* Center Section */
.dashboard-center {
    flex: 1.4;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 1.25rem;
}
.dashboard-btn {
    background-color: #649D5F;
    color: #333333;
    border: none;
    padding: 0.75rem 2rem;
    border-radius: 25px;
    font-size: 1rem;
    cursor: pointer;
    transition: background 0.3s ease;
    width: 300px;
    text-align: center;
}
.dashboard-btn:hover {
    background-color: #4b8d47;
}
.dashboard-right {
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    align-items: center;
}


